{
  "items": [
    {
      "name": "Real.pow_le_iff_le_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℕ}, 0 < x → 0 < y → (x ^ n ≤ y ↔ ↑n * Real.log x ≤ Real.log y)"
    },
    {
      "name": "Real.pow_le_of_le_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℕ}, 0 < y → Real.log x ≤ ↑n * Real.log y → x ≤ y ^ n"
    },
    {
      "name": "Real.pow_lt_iff_lt_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℕ}, 0 < x → 0 < y → (x ^ n < y ↔ ↑n * Real.log x < Real.log y)"
    },
    {
      "name": "Real.zpow_le_iff_le_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℤ}, 0 < x → 0 < y → (x ^ n ≤ y ↔ ↑n * Real.log x ≤ Real.log y)"
    },
    {
      "name": "Real.le_pow_iff_log_le",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℕ}, 0 < x → 0 < y → (x ≤ y ^ n ↔ Real.log x ≤ ↑n * Real.log y)"
    }
  ]
}
